import React, { useContext } from 'react';
import { FormattedMessage } from 'react-intl';

import { ViewOffIcon } from '@dynatrace/strato-icons';

import { useTableUserActionsContext } from './useTableUserActionsContext.js';
import { Menu } from '../../../../navigation/menu/Menu.js';
import { DataTableContext } from '../../../contexts/DataTableContext.js';
import { dataTableMessages } from '../../../DataTable/messages.js';
import type { ColumnMinInstance } from '../../../types/internal-table-types.js';
import { getUpdatedVisibility } from '../../../utils/visibility-utils.js';

export const HideColumn = () => {
  const tableActionContext = useTableUserActionsContext();
  const { columnVisibility, onVisibilityChange, allColumns } =
    useContext(DataTableContext);

  if (tableActionContext === null || !onVisibilityChange) {
    return null;
  }

  const { column } = tableActionContext;

  return (
    <Menu.Item
      onSelect={() => {
        const updatedVisiblity = getUpdatedVisibility(
          columnVisibility,
          'hidden',
          (allColumns as ColumnMinInstance[]) ?? [],
          column.id,
        );

        onVisibilityChange(updatedVisiblity);
      }}
    >
      <Menu.ItemIcon>
        <ViewOffIcon />
      </Menu.ItemIcon>
      <FormattedMessage {...dataTableMessages.hideColumnLabel} />
    </Menu.Item>
  );
};

HideColumn['displayName'] = 'TableUserActions.HideColumn';
